import threading
import webbrowser
import socket
import base64
import json
import sys
import urllib.parse
import urllib.request
import tkinter as tk
import time
import os
import hashlib
from pathlib import Path
from tkinter import filedialog
from socketserver import ThreadingMixIn
from http.server import HTTPServer, SimpleHTTPRequestHandler

PS4_IP = "192.168.0.2"

RPI_PORT = 12800
HTTP_PORT = 8080
BINLOADER_PORTS = [9090, 9020]

#=============================================================================================#
#                                                                                            #
#                                                                                            #
#        This payload - RPI Payload to install .pkg directly, without any other app.         #
#        Link to repository of Payload - https://github.com/neeitr0n/ps4-rpi-payload         #
#         Original author and repo - https://github.com/cfgcodelab/PS4-RPI-Payload/          #
#                 It's very long (30k of symbols), so don't try to read it                   #
#                                               |                                            #
#                                               |                                            #
#                                               ↓                                            #

PAYLOAD_B64 = ""

SELECTED_FILES = []
FILES_MAP = {}
FILES_LAST_ACCESS = {}
PROGRESS_MAP = {}

PROGRESS_LOCK = threading.Lock()

PROGRESS_DONE_TTL = 3.0
PROGRESS_SPEED_IDLE_TIMEOUT = 3.0
PROGRESS_ACTIVE_IDLE_TIMEOUT = 10.0
PROGRESS_QUEUED_TIMEOUT = 90.0

FILE_REGISTRATION_TTL = 3600.0

HTML_PAGE = Path(__file__).parent / "index.html"


def get_local_ip(ip_addr):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.connect((ip_addr, 80))
            local_ip = s.getsockname()[0]

        return local_ip, None

    except OSError as err:
        return None, err


def is_port_open(ip: str, port: int, timeout: float = 1.0) -> bool:
    try:
        with socket.create_connection((ip, port), timeout=timeout):
            return True
    except OSError:
        return False


# После выхода PS4 из Rest Mode сеть и сервисы GoldHEN могут подниматься
# не одновременно. Не считаем единичный отказ TCP-подключения окончательным.
BINLOADER_WAIT_TIMEOUT = 20.0
BINLOADER_CONNECT_TIMEOUT = 1.5
BINLOADER_RETRY_INTERVAL = 1.0
RPI_PROBE_TIMEOUT = 0.75
RPI_START_TIMEOUT = 12.0


def ensure_rpi_running(ps4_ip: str, rpi_port: int = 12800) -> tuple[bool, str]:
    # RPI уже запущен: повторно внедрять payload не нужно.
    if is_port_open(ps4_ip, rpi_port, timeout=RPI_PROBE_TIMEOUT):
        return True, "RPI уже активен"

    payload_bytes = base64.b64decode(PAYLOAD_B64)
    wait_deadline = time.monotonic() + BINLOADER_WAIT_TIMEOUT
    last_errors = {port: "подключение ещё не проверялось" for port in BINLOADER_PORTS}
    connected_port = None

    # Ждём, пока PS4 после пробуждения снова начнёт принимать TCP-соединения.
    while time.monotonic() < wait_deadline:
        # Возможно, RPI успел восстановиться сам, пока мы ждали.
        if is_port_open(ps4_ip, rpi_port, timeout=RPI_PROBE_TIMEOUT):
            return True, "RPI стал доступен после пробуждения"

        for loader_port in BINLOADER_PORTS:
            try:
                sock = socket.create_connection(
                    (ps4_ip, loader_port),
                    timeout=BINLOADER_CONNECT_TIMEOUT
                )
            except OSError as err:
                last_errors[loader_port] = f"{type(err).__name__}: {err}"
                continue

            # TCP-соединение установлено. Если отправка началась, но оборвалась,
            # не пробуем второй порт: первый payload мог быть принят частично.
            try:
                with sock:
                    sock.sendall(payload_bytes)
            except OSError as err:
                return (
                    False,
                    f"BinLoader на порту {loader_port} принял TCP-соединение, "
                    f"но отправка payload завершилась ошибкой: "
                    f"{type(err).__name__}: {err}"
                )

            connected_port = loader_port
            break

        if connected_port is not None:
            break

        time.sleep(BINLOADER_RETRY_INTERVAL)

    if connected_port is None:
        details = "; ".join(
            f"{port}: {error}" for port, error in last_errors.items()
        )
        return (
            False,
            f"BinLoader не принял соединение за {BINLOADER_WAIT_TIMEOUT:.0f} с. "
            f"Ошибки подключения — {details}. Проверьте IP PS4, настройку "
            f"Enable BinLoader Server и Enable Rest Mode Support в GoldHEN."
        )

    # Payload был отправлен ровно один раз. Теперь ждём запуска его HTTP-сервера.
    start_deadline = time.monotonic() + RPI_START_TIMEOUT
    while time.monotonic() < start_deadline:
        if is_port_open(ps4_ip, rpi_port, timeout=RPI_PROBE_TIMEOUT):
            return True, f"Payload загружен через BinLoader :{connected_port}"
        time.sleep(0.5)

    return (
        False,
        f"Payload отправлен через BinLoader :{connected_port}, "
        f"но RPI-порт {rpi_port} не открылся за {RPI_START_TIMEOUT:.0f} с. "
        f"Возможна ошибка запуска payload или проблема восстановления GoldHEN после Rest Mode."
    )


class Handler(SimpleHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def send_json(self, data):
        raw = json.dumps(data, ensure_ascii=False).encode("utf-8")

        self.send_response(200)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(raw)))
        self.send_header("Connection", "close")
        self.end_headers()

        self.wfile.write(raw)

    def do_HEAD(self):
        if self.path.startswith("/pkg/"):
            self.handle_pkg(False)
        else:
            self.send_error(404)

    def do_GET(self):
        global SELECTED_FILES

        u = urllib.parse.urlparse(self.path)

        if u.path == "/":
            page = HTML_PAGE.read_bytes()

            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(page)))
            self.send_header("Connection", "close")
            self.end_headers()

            self.wfile.write(page)

        elif u.path == "/api/pick":
            root = tk.Tk()
            root.withdraw()
            root.attributes('-topmost', True)

            paths = filedialog.askopenfilenames(
                title="Выберите PKG файлы",
                filetypes=[
                    ("PS4 Packages", "*.pkg"),
                    ("Все файлы", "*.*")
                ]
            )

            root.destroy()

            if paths:
                SELECTED_FILES = list(paths)

            self.send_json({"files": SELECTED_FILES})

        elif u.path == "/api/progress":
            now = time.monotonic()

            with PROGRESS_LOCK:
                expired = []

                for tok, info in PROGRESS_MAP.items():

                    if info.get("done"):
                        finished_at = info.get("finished_at")

                        if (
                            finished_at
                            and now - finished_at > PROGRESS_DONE_TTL
                        ):
                            expired.append(tok)

                        continue

                    last_activity = info.get(
                        "last_activity",
                        info.get("created_at", now)
                    )

                    idle_for = now - last_activity

                    if idle_for > PROGRESS_SPEED_IDLE_TIMEOUT:
                        info["speed"] = 0.0

                    timeout = (
                        PROGRESS_ACTIVE_IDLE_TIMEOUT
                        if info.get("started")
                        else PROGRESS_QUEUED_TIMEOUT
                    )

                    if idle_for > timeout:
                        expired.append(tok)

                for tok in expired:
                    PROGRESS_MAP.pop(tok, None)

                expired_files = [
                    tok
                    for tok, last_access in FILES_LAST_ACCESS.items()
                    if now - last_access > FILE_REGISTRATION_TTL
                ]

                for tok in expired_files:
                    FILES_MAP.pop(tok, None)
                    FILES_LAST_ACCESS.pop(tok, None)
                    PROGRESS_MAP.pop(tok, None)

                snapshot = {
                    tok: {
                        key: value
                        for key, value in info.items()
                        if key not in (
                            "created_at",
                            "last_activity",
                            "started"
                        )
                    }
                    for tok, info in PROGRESS_MAP.items()
                }

            self.send_json(snapshot)

        elif u.path.startswith("/pkg/"):
            self.handle_pkg(True)

        else:
            self.send_error(404)

    def do_POST(self):

        if self.path == "/api/remove":
            length = int(self.headers.get("Content-Length", 0))
            body = json.loads(self.rfile.read(length).decode("utf-8"))

            file_path = body.get("path")

            if not file_path:
                return self.send_json({
                    "ok": False,
                    "err": "Не указан путь к файлу"
                })

            if file_path in SELECTED_FILES:
                SELECTED_FILES.remove(file_path)

                return self.send_json({
                    "ok": True,
                    "files": SELECTED_FILES
                })

            return self.send_json({
                "ok": False,
                "err": "Файл не найден в очереди"
            })

        if self.path == "/api/send":
            length = int(self.headers.get("Content-Length", 0))

            body = json.loads(
                self.rfile.read(length).decode("utf-8")
            )

            ps4_ip = body.get("ip", PS4_IP)
            pc_ip, err = get_local_ip(ps4_ip)

            if pc_ip is None:
                return self.send_json({
                    "ok": False,
                    "err": f"Не удалось определить IP ПК: {err}"
                })

            valid_files = [
                fp for fp in SELECTED_FILES
                if os.path.isfile(fp)
            ]

            if not valid_files:
                return self.send_json({
                    "ok": False,
                    "err": "Сначала выберите файлы"
                })

            ok, status_message = ensure_rpi_running(
                ps4_ip,
                RPI_PORT
            )

            if not ok:
                return self.send_json({
                    "ok": False,
                    "err": status_message
                })

            responses = []

            try:
                for i, file_path in enumerate(valid_files):
                    md5_token = hashlib.md5(
                        file_path.encode("utf-8")
                    ).hexdigest()

                    created_at = time.monotonic()

                    with PROGRESS_LOCK:
                        PROGRESS_MAP[md5_token] = {
                            "name": os.path.basename(file_path),
                            "total": os.path.getsize(file_path),
                            "sent": 0,
                            "speed": 0.0,
                            "done": False,
                            "finished_at": None,
                            "created_at": created_at,
                            "last_activity": created_at,
                            "started": False,
                        }

                        FILES_MAP[md5_token] = file_path
                        FILES_LAST_ACCESS[md5_token] = created_at

                    single_url = (
                        f"http://{pc_ip}:{HTTP_PORT}"
                        f"/pkg/{md5_token}.pkg"
                    )

                    req = urllib.request.Request(
                        f"http://{ps4_ip}:{RPI_PORT}/api/install",
                        data=json.dumps({
                            "type": "direct",
                            "packages": [single_url]
                        }).encode("utf-8"),
                        headers={
                            "Content-Type": "application/json"
                        },
                        method="POST",
                    )

                    with urllib.request.urlopen(req, timeout=15) as r:
                        responses.append(
                            json.loads(r.read().decode("utf-8"))
                        )

                    if i < len(valid_files) - 1:
                        time.sleep(1.5)

                self.send_json({
                    "ok": True,
                    "ps4_response": responses
                })

            except Exception as e:
                self.send_json({
                    "ok": False,
                    "err": str(e)
                })

    def handle_pkg(self, send_body):
        clean_path = urllib.parse.urlparse(self.path).path

        md5_token = (
            os.path.basename(clean_path)
            .replace(".pkg", "")
        )

        now = time.monotonic()

        with PROGRESS_LOCK:
            file_path = FILES_MAP.get(md5_token)
            if file_path:
                FILES_LAST_ACCESS[md5_token] = now

        if not file_path or not os.path.isfile(file_path):
            print(f"[DEBUG 404] path={self.path} | token={md5_token} | file_path={file_path} | exists={os.path.exists(str(file_path))}")
            return self.send_error(404)

        file_size = os.path.getsize(file_path)

        with PROGRESS_LOCK:
            info = PROGRESS_MAP.get(md5_token)

            if info is None or info.get("done"):
                info = {
                    "name": os.path.basename(file_path),
                    "total": file_size,
                    "sent": 0,
                    "speed": 0.0,
                    "done": False,
                    "finished_at": None,
                    "created_at": now,
                    "last_activity": now,
                    "started": True,
                }
                PROGRESS_MAP[md5_token] = info
            else:
                info["started"] = True
                info["last_activity"] = now

        range_bytes = self.headers.get("Range")

        start, end, code = 0, file_size - 1, 200

        if range_bytes and range_bytes.startswith("bytes="):
            part_start, _, part_end = (
                range_bytes.replace("bytes=", "").partition("-")
            )

            if part_start:
                start = int(part_start)

            if part_end:
                end = int(part_end)

            code = 206

        content_length = end - start + 1

        try:
            self.request.setsockopt(
                socket.SOL_SOCKET,
                socket.SO_SNDBUF,
                4194304
            )

            self.request.setsockopt(
                socket.IPPROTO_TCP,
                socket.TCP_NODELAY,
                1
            )

            self.send_response(code)

            self.send_header(
                "Content-Type",
                "application/octet-stream"
            )

            self.send_header(
                "Content-Disposition",
                f'attachment; filename="{md5_token}.pkg"'
            )

            self.send_header("Accept-Ranges", "bytes")
            self.send_header("Content-Length", str(content_length))
            self.send_header("Connection", "close")

            if code == 206:
                self.send_header(
                    "Content-Range",
                    f"bytes {start}-{end}/{file_size}"
                )

            self.end_headers()

            if not send_body:
                return

            self.wfile.flush()

            last_time = time.monotonic()
            bytes_since_last = 0

            with open(file_path, "rb") as file:

                if hasattr(os, "sendfile"):
                    offset = start
                    remaining = content_length

                    while remaining > 0:
                        sent = os.sendfile(
                            self.wfile.fileno(),
                            file.fileno(),
                            offset,
                            remaining
                        )

                        if sent == 0:
                            break

                        offset += sent
                        remaining -= sent
                        bytes_since_last += sent

                        now = time.monotonic()

                        with PROGRESS_LOCK:
                            FILES_LAST_ACCESS[md5_token] = now
                            info = PROGRESS_MAP.get(md5_token)

                            if info and not info.get("done"):
                                info["started"] = True
                                info["last_activity"] = now
                                info["sent"] = offset

                                if now - last_time >= 0.5:
                                    speed = (
                                        bytes_since_last / (1024 * 1024)
                                    ) / (now - last_time)

                                    info["speed"] = round(speed, 1)

                                    bytes_since_last = 0
                                    last_time = now

                else:
                    file.seek(start)

                    offset = start
                    remaining = content_length

                    while remaining > 0:
                        chunk = file.read(
                            min(8388608, remaining)
                        )

                        if not chunk:
                            break

                        self.wfile.write(chunk)

                        chunk_len = len(chunk)

                        offset += chunk_len
                        remaining -= chunk_len
                        bytes_since_last += chunk_len

                        now = time.monotonic()

                        with PROGRESS_LOCK:
                            FILES_LAST_ACCESS[md5_token] = now
                            info = PROGRESS_MAP.get(md5_token)

                            if info and not info.get("done"):
                                info["started"] = True
                                info["last_activity"] = now
                                info["sent"] = offset

                                if now - last_time >= 0.5:
                                    speed = (
                                        bytes_since_last / (1024 * 1024)
                                    ) / (now - last_time)

                                    info["speed"] = round(speed, 1)

                                    bytes_since_last = 0
                                    last_time = now

            if start + content_length >= file_size and remaining == 0:

                with PROGRESS_LOCK:
                    if md5_token in PROGRESS_MAP:
                        PROGRESS_MAP[md5_token]["sent"] = file_size
                        PROGRESS_MAP[md5_token]["speed"] = 0.0
                        PROGRESS_MAP[md5_token]["done"] = True

                        finished_at = time.monotonic()

                        PROGRESS_MAP[md5_token]["finished_at"] = finished_at
                        PROGRESS_MAP[md5_token]["last_activity"] = finished_at
                        FILES_LAST_ACCESS[md5_token] = finished_at

                if file_path in SELECTED_FILES:
                    SELECTED_FILES.remove(file_path)

        except (
            BrokenPipeError,
            ConnectionResetError,
            ConnectionAbortedError,
            OSError
        ):
            with PROGRESS_LOCK:
                info = PROGRESS_MAP.get(md5_token)

                if info and not info.get("done"):
                    info["speed"] = 0.0
                    info["last_activity"] = time.monotonic()


class ThreadedHTTPServer(ThreadingMixIn, HTTPServer):
    daemon_threads = True


if __name__ == "__main__":
    local_ip, err = get_local_ip(PS4_IP)

    if local_ip is None:
        print(f"error: {err}\nexiting...")
        sys.exit(1)

    print(f"your local ip address: {local_ip}")

    with ThreadedHTTPServer(
        ("0.0.0.0", HTTP_PORT),
        Handler
    ) as s:

        try:
            threading.Timer(
                0.5,
                webbrowser.open,
                args=[f"http://{local_ip}:{HTTP_PORT}/"]
            ).start()

            s.serve_forever()

        except KeyboardInterrupt:
            print("\nstopped")
